// Build docs/mamba-schema.postgres.sql — the PostgreSQL translation of
// docs/mamba-schema.sql (v3) + docs/mamba-schema-v4.sql (v4).
//
//   node tools/pg/build-postgres.mjs
//
// Translation rules (SQLite → PostgreSQL):
//   · PRAGMA / user_version            → dropped (SQLite-only)
//   · INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
//   · REAL / BLOB                      → DOUBLE PRECISION / BYTEA
//   · TEXT timestamps                  → kept as TEXT on purpose: the app writes
//                                        ISO-8601 strings ('2026-07-26T13:00:00Z')
//                                        everywhere, so switching to timestamptz
//                                        would break every existing query.
//   · 0/1 flags                        → kept as INTEGER + CHECK, same reason.
//   · Foreign keys                     → emitted as ALTER TABLE at the end, because
//                                        the SQLite file forward-references tables
//                                        (project_leads → campaign_runs) which
//                                        Postgres rejects inside CREATE TABLE.
//   · strftime('%Y-%m-%dT%H:%M:%fZ','now') → to_char(now() AT TIME ZONE 'UTC', …)
//   · Comments in the .sql             → COMMENT ON TABLE / COLUMN
import { writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';
import { parseSchema, parseSchemaText } from '../lib/parse-schema.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
const OUT = join(ROOT, 'docs/mamba-schema.postgres.sql');
const DB_PATH = join(ROOT, 'campaign-data/mamba.sqlite');

const tables = parseSchema([
  { path: join(ROOT, 'docs/mamba-schema.sql'), version: 'v3' },
  { path: join(ROOT, 'docs/mamba-schema-v4.sql'), version: 'v4' },
]);

// 真实库里还有几张服务自己装的表(followup_log / lid_map / instance_identity …),
// 文档 schema 没收录。要把全量数据搬上 Postgres,这些表也得建。
if (existsSync(DB_PATH)) {
  const db = new DatabaseSync(DB_PATH, { readOnly: true });
  const ddl = db
    .prepare("SELECT sql FROM sqlite_master WHERE type='table' AND sql IS NOT NULL AND name NOT LIKE 'sqlite_%'")
    .all()
    .map((r) => r.sql.replace(/^CREATE TABLE\s+(?:IF NOT EXISTS\s+)?["`[]?(\w+)["`\]]?\s*\(/i, 'CREATE TABLE IF NOT EXISTS $1 ('))
    .join(';\n');
  db.close();
  const known = new Set(tables.map((t) => t.name));
  for (const t of parseSchemaText(ddl)) {
    if (known.has(t.name)) continue;
    t.desc = t.desc || '真实库里存在、文档 schema 未收录的表';
    tables.push(t);
  }
}

// v4 的迁移脚本用 ALTER TABLE 加了这一列(SQLite 不支持 ADD COLUMN IF NOT EXISTS),
// 建新库时直接写进 project_leads。见 campaign-app/migrate_v3_to_v4.mjs。
const leads = tables.find((t) => t.name === 'project_leads');
leads.columns.push({
  name: 'assigned_account_key', type: 'TEXT', pk: false, autoincrement: false,
  notnull: false, unique: false, default: null, check: null, enum: null,
  ref: { table: 'whatsapp_accounts', column: 'account_key' },
  note: 'v4:该 lead 归哪个 WhatsApp 账号', onDelete: 'SET NULL',
});
(leads.indexes ||= []).push({ name: 'idx_leads_account', unique: false, cols: 'assigned_account_key', where: '' });

const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";

function pgType(c) {
  if (c.autoincrement) return 'BIGINT GENERATED BY DEFAULT AS IDENTITY';
  return { TEXT: 'TEXT', INTEGER: 'INTEGER', REAL: 'DOUBLE PRECISION', BLOB: 'BYTEA', NUMERIC: 'NUMERIC' }[c.type] || 'TEXT';
}

// ON DELETE 动作写在 SQLite 的表级 FOREIGN KEY 子句里,解析后要找回来。
function onDeleteOf(t, colName) {
  for (const con of t.constraints) {
    const m = con.match(/^FOREIGN KEY\s*\((\w+)\)\s*REFERENCES\s+\w+\s*\(\w+\)\s*(?:ON DELETE (CASCADE|RESTRICT|SET NULL|SET DEFAULT|NO ACTION))?/i);
    if (m && m[1] === colName) return m[2] || null;
  }
  return null;
}

const out = [];
const P = (s = '') => out.push(s);

P('-- =============================================================================');
P('-- Mamba schema for PostgreSQL');
P(`-- 由 tools/pg/build-postgres.mjs 从 docs/mamba-schema.sql (v3) + docs/mamba-schema-v4.sql (v4)`);
P(`-- 生成于 ${new Date().toISOString()}。不要手改这个文件,改上面两个源文件再重新生成。`);
P('--');
P('-- 用法:');
P('--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f docs/mamba-schema.postgres.sql');
P('--');
P('-- 说明:');
P('--   · 时间列保持 TEXT(应用写的是 ISO-8601 字符串),不改成 timestamptz。');
P('--   · 0/1 标志位保持 INTEGER + CHECK,和 SQLite 行为一致。');
P('--   · 外键统一放在文件末尾的 ALTER TABLE,避免建表顺序问题。');
P('-- =============================================================================');
P();
P('BEGIN;');
P("SET client_min_messages = warning;   -- 首次执行时 DROP CONSTRAINT IF EXISTS 的 NOTICE 太吵");
P();

// ---- 1. tables ----
for (const t of tables) {
  if (t.desc) P(`-- ${t.desc}`);
  const lines = [];
  const single = t.columns.filter((c) => c.pk).length === 1;
  for (const c of t.columns) {
    let s = `  ${c.name.padEnd(22)} ${pgType(c)}`;
    if (c.pk && single) s += ' PRIMARY KEY';
    if (c.notnull && !(c.pk && single)) s += ' NOT NULL';
    if (c.default !== null) s += ` DEFAULT ${c.default}`;
    if (c.unique) s += ' UNIQUE';
    if (c.check) s += ` CHECK (${c.check})`;
    lines.push(s);
  }
  // 每一行都盖章:哪台电脑传上来的、什么时候传的。
  // 这是「哪台电脑发的」唯一可靠的答案 —— messages 这类表本身没有归属栏位,
  // 但每台电脑只同步自己的资料,所以同步当下就是事实,不需要推导。
  lines.push(`  ${'source_device_key'.padEnd(22)} TEXT NOT NULL DEFAULT ''`);
  lines.push(`  ${'synced_at'.padEnd(22)} TEXT NOT NULL DEFAULT ''`);
  for (const con of t.constraints) {
    if (/^FOREIGN KEY/i.test(con)) continue;         // 放到末尾统一 ALTER
    lines.push('  ' + con);
  }
  P(`CREATE TABLE IF NOT EXISTS ${t.name} (`);
  P(lines.join(',\n'));
  P(');');
  P();
}

// ---- 1b. 旧库补栏位(CREATE TABLE IF NOT EXISTS 不会帮你加新栏位)----
P('-- ---------------------------------------------------------------------------');
P('-- 来源栏位(已经建过表的库靠这段补上)');
P('-- ---------------------------------------------------------------------------');
for (const t of tables) {
  P(`ALTER TABLE ${t.name} ADD COLUMN IF NOT EXISTS source_device_key TEXT NOT NULL DEFAULT '';`);
  P(`ALTER TABLE ${t.name} ADD COLUMN IF NOT EXISTS synced_at TEXT NOT NULL DEFAULT '';`);
}
P();
for (const t of tables) {
  P(`CREATE INDEX IF NOT EXISTS idx_${t.name}_source_device ON ${t.name} (source_device_key);`);
}
P();

// ---- 1c. 同步台账 ----
P('-- 每台电脑每次同步一行:谁、什么时候、传了多少');
P(`CREATE TABLE IF NOT EXISTS sync_runs (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_device_key TEXT NOT NULL,
  device_name       TEXT NOT NULL DEFAULT '',
  sender_phone      TEXT NOT NULL DEFAULT '',
  started_at        TEXT NOT NULL,
  rows_total        INTEGER NOT NULL DEFAULT 0,
  detail_json       TEXT NOT NULL DEFAULT '{}'
);`);
P('CREATE INDEX IF NOT EXISTS idx_sync_runs_device ON sync_runs (source_device_key, started_at);');
P();

// ---- 2. indexes ----
P('-- ---------------------------------------------------------------------------');
P('-- 索引');
P('-- ---------------------------------------------------------------------------');
for (const t of tables) {
  for (const i of t.indexes || []) {
    P(`CREATE ${i.unique ? 'UNIQUE ' : ''}INDEX IF NOT EXISTS ${i.name}`);
    P(`  ON ${t.name} (${i.cols})${i.where ? '\n  ' + i.where : ''};`);
  }
}
P();

// ---- 3. foreign keys ----
P('-- ---------------------------------------------------------------------------');
P('-- 外键(放最后,避免 project_leads → campaign_runs 这类前向引用)');
P('-- ---------------------------------------------------------------------------');
for (const t of tables) {
  for (const c of t.columns) {
    if (!c.ref) continue;
    const act = c.onDelete || onDeleteOf(t, c.name);
    const name = `fk_${t.name}_${c.name}`;
    P(`ALTER TABLE ${t.name} DROP CONSTRAINT IF EXISTS ${name};`);
    P(`ALTER TABLE ${t.name} ADD CONSTRAINT ${name}`);
    P(`  FOREIGN KEY (${c.name}) REFERENCES ${c.ref.table}(${c.ref.column})${act ? ' ON DELETE ' + act : ''};`);
  }
}
P();

// ---- 4. comments ----
P('-- ---------------------------------------------------------------------------');
P('-- 注释(pgAdmin / Supabase 表视图里能直接看到)');
P('-- ---------------------------------------------------------------------------');
for (const t of tables) {
  if (t.desc) P(`COMMENT ON TABLE ${t.name} IS ${q(t.desc)};`);
  for (const c of t.columns) {
    if (c.note) P(`COMMENT ON COLUMN ${t.name}.${c.name} IS ${q(c.note)};`);
  }
}
P();

// ---- 5. seed ----
const NOW = `to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')`;
P('-- ---------------------------------------------------------------------------');
P('-- 种子数据(幂等)');
P('-- ---------------------------------------------------------------------------');
P(`INSERT INTO sync_worker_state (id, enabled, mode, status, updated_at)`);
P(`VALUES ('singleton', 0, 'SHADOW', 'IDLE', ${NOW})`);
P('ON CONFLICT (id) DO NOTHING;');
P();
P(`INSERT INTO schema_migrations (version, name, applied_at) VALUES`);
P(`  (3, 'systematic-business-schema', ${NOW}),`);
P(`  (4, 'account-device-binding-and-send-ledger', ${NOW})`);
P('ON CONFLICT (version) DO NOTHING;');
P();
P(`INSERT INTO metadata (key, value, updated_at) VALUES`);
P(`  ('schema_version', '4', ${NOW}),`);
P(`  ('storage_mode', 'shadow', ${NOW}),`);
P(`  ('account_binding_mode', 'shadow', ${NOW}),`);
P(`  ('send_claims_enforced', 'false', ${NOW}),`);
P(`  ('handoff_enabled', 'false', ${NOW})`);
P('ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at;');
P();
P('COMMIT;');

writeFileSync(OUT, out.join('\n') + '\n');
const fkCount = tables.reduce((n, t) => n + t.columns.filter((c) => c.ref).length, 0);
const idxCount = tables.reduce((n, t) => n + (t.indexes || []).length, 0);
console.log(`✓ ${OUT}`);
console.log(`  ${tables.length} 张表 · ${fkCount} 个外键 · ${idxCount} 个索引`);
